#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main(void)
{
    int n, x, c[101];
    vector<int> a[101];

    cin >> n;
    for(int i = 1; i <= n; i++){
    	cin >> c[i];
        a[i].resize(c[i]);
        for(int j = 0; j < c[i]; j++) cin >> a[i][j];
    }
    cin >> x;

    vector<int> vec;
    for(int i = 1; i <= n; i++){
        for(int j = 0; j < c[i]; j++) if(a[i][j] == x) vec.push_back(i);
    }

    int cmin = 37;
    for(auto i : vec) cmin = min(cmin, c[i]);

    vector<int> ans;
    for(auto i : vec) if(c[i] == cmin) ans.push_back(i);

    cout << ans.size() << endl;
    for(auto b : ans) cout << b << " ";
    cout << endl;

    return 0;
}

#include <algorithm>
#include <iostream>
#include <ranges>
#include <vector>
using namespace std;

int main() {
    int N;
    cin >> N;
    vector bet(N, vector<int>{});
    for(auto& A : bet) {
        int C;
        cin >> C;
        A.resize(C);
        for(int& a : A) cin >> a;
    }
    int X;
    cin >> X;

    auto contains_X = views::iota(0, N) | views::filter([&](int i){ return ranges::count(bet[i], X); });
    if(ranges::empty(contains_X)) {
        cout << "0\n";
        return 0;
    }
    auto min_size = ranges::min(contains_X | views::transform([&](int i){ return bet[i].size(); }));
    auto ans = contains_X | views::filter([&](int i){ return bet[i].size() == min_size; });

    cout << ranges::distance(ans) << '\n';
    for(auto i : ans) cout << i + 1 << '\n';
}
